WITH obs AS (
SELECT DATE dt, 'SALE_RK' src, LOWER(REGEXP_REPLACE(URL,r'^.*/p/([^/?#]+).*$',r'\1')) id, CAT cat, BRAND brand FROM `pjt-lge-oned.L2_ONED.VSMRKT_DAILY_OSM_SALE_RK_D` WHERE DATE IN (DATE '2026-10-26', DATE '2026-11-14', DATE '2026-11-15', DATE '2026-11-16', DATE '2026-11-17', DATE '2026-11-18') AND UPPER(TRIM(ONLINE_STR))='MAGAZINELUIZA' AND UPPER(TRIM(CNTRY))='BRAZIL' UNION ALL
SELECT DATE dt, 'BANR_VSBLT' src, LOWER(REGEXP_REPLACE(URL,r'^.*/p/([^/?#]+).*$',r'\1')) id, CAT cat, BRAND brand FROM `pjt-lge-oned.L2_ONED.VSMRKT_DAILY_OSM_BANR_VSBLT_D` WHERE DATE IN (DATE '2026-10-26', DATE '2026-11-14', DATE '2026-11-15', DATE '2026-11-16', DATE '2026-11-17', DATE '2026-11-18') AND UPPER(TRIM(ONLINE_STR))='MAGAZINELUIZA' AND UPPER(TRIM(CNTRY))='BRAZIL'
 UNION ALL
 SELECT BASE_DATE dt,'DETAIL' src,LOWER(REGEXP_REPLACE(PRODUCT_PAGE_URL_ADDR,r'^.*/p/([^/?#]+).*$',r'\1')) id, NULL cat,NULL brand FROM `pjt-lge-oned.L1_ONED.TRPURC_OSM_PRODUCT_DAILY_L` WHERE BASE_DATE IN (DATE '2026-10-26',DATE '2026-11-14', DATE '2026-11-15', DATE '2026-11-16', DATE '2026-11-17', DATE '2026-11-18') AND UPPER(TRIM(SITE_NAME))='MAGAZINELUIZA' AND UPPER(TRIM(CNTRY_CODE))='BR'
)
